ALTER POLICY "Masters manage own saved attacks" ON public.saved_attacks USING (public.has_role(auth.uid(), 'master')) WITH CHECK (public.has_role(auth.uid(), 'master'));
ALTER POLICY "Masters manage own saved creatures" ON public.saved_creatures USING (public.has_role(auth.uid(), 'master')) WITH CHECK (public.has_role(auth.uid(), 'master'));
ALTER POLICY "Masters manage own groups" ON public.saved_creature_groups USING (public.has_role(auth.uid(), 'master')) WITH CHECK (public.has_role(auth.uid(), 'master'));
ALTER POLICY "Masters manage own group members" ON public.saved_creature_group_members USING (public.has_role(auth.uid(), 'master')) WITH CHECK (public.has_role(auth.uid(), 'master'));
ALTER POLICY "Only masters can access notes" ON public.notes USING (public.has_role(auth.uid(), 'master')) WITH CHECK (public.has_role(auth.uid(), 'master'));
ALTER POLICY "Masters can create documents" ON public.documents WITH CHECK (public.has_role(auth.uid(), 'master'));
ALTER POLICY "Masters can update documents" ON public.documents USING (public.has_role(auth.uid(), 'master')) WITH CHECK (public.has_role(auth.uid(), 'master'));
ALTER POLICY "Masters can delete documents" ON public.documents USING (public.has_role(auth.uid(), 'master'));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.saved_attacks, public.saved_creatures, public.saved_creature_groups, public.saved_creature_group_members, public.notes, public.documents TO authenticated;
GRANT ALL ON public.saved_attacks, public.saved_creatures, public.saved_creature_groups, public.saved_creature_group_members, public.notes, public.documents TO service_role;
CREATE TABLE public.saved_combats (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, state jsonb NOT NULL DEFAULT '{"combatants":[],"turnIdx":0,"round":1,"addedGroupIds":[]}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.saved_combats TO authenticated;
GRANT ALL ON public.saved_combats TO service_role;
ALTER TABLE public.saved_combats ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Masters share saved combats" ON public.saved_combats FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'master')) WITH CHECK (public.has_role(auth.uid(), 'master'));
CREATE TRIGGER saved_combats_updated BEFORE UPDATE ON public.saved_combats FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TABLE public.current_status (slot integer PRIMARY KEY, name text NOT NULL DEFAULT '', max_hp integer NOT NULL DEFAULT 0, current_hp integer NOT NULL DEFAULT 0, notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.current_status TO authenticated;
GRANT ALL ON public.current_status TO service_role;
ALTER TABLE public.current_status ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Signed in users view status" ON public.current_status FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
CREATE POLICY "Signed in users edit status" ON public.current_status FOR UPDATE TO authenticated USING (auth.uid() IS NOT NULL) WITH CHECK (auth.uid() IS NOT NULL);
CREATE FUNCTION public.validate_current_status() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.slot < 1 OR NEW.slot > 8 THEN RAISE EXCEPTION 'Status board has exactly eight slots'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER current_status_validate BEFORE INSERT OR UPDATE ON public.current_status FOR EACH ROW EXECUTE FUNCTION public.validate_current_status();
CREATE TRIGGER current_status_updated BEFORE UPDATE ON public.current_status FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
INSERT INTO public.current_status(slot) SELECT generate_series(1,8);